import {COURT,wallX} from './court-geometry.js';
export function beginPointEnd(ball,side,changed){if(ball.caughtOpening){const g=ball.caughtOpening==='service'?COURT.dedans:COURT.grille,sign=ball.caughtOpening==='service'?1:-1;ball.vx=ball.vy=ball.vz=0;return {side,changed,remaining:3.2,pocket:{x:Math.max(g.x-g.w/2+.13,Math.min(g.x+g.w/2-.13,ball.x)),y:g.y-g.h/2+.095,z:sign*((sign===1?COURT.halfLength:COURT.endRoofInner)+.22)}};}ball.vx*=.16;ball.vz*=.16;if(ball.y>=0&&ball.y<=.11){ball.y=.095;ball.vy=Math.min(1.2,Math.abs(ball.vy)*.22);}return {side,changed,remaining:3.2};}
export function advancePointEnd(state,ball,dt){state.remaining-=dt;if(state.pocket){const k=1-Math.exp(-Math.max(0,dt)*12);for(const axis of ['x','y','z'])ball[axis]+=(state.pocket[axis]-ball[axis])*k;ball.vx=ball.vy=ball.vz=0;return state.remaining<=0;}if(ball.y>=0){for(let left=dt;left>1e-7;){const h=Math.min(left,1/120);left-=h;ball.vy-=9.81*h;ball.x+=ball.vx*h;ball.z+=ball.vz*h;ball.y+=ball.vy*h;ball.x=Math.max(-4.7,Math.min(wallX(ball.z)-.1,ball.x));ball.z=Math.max(-COURT.endRoofInner+.1,Math.min(COURT.halfLength-.1,ball.z));if(ball.y<.095){ball.y=.095;ball.vy=Math.abs(ball.vy)*.18;ball.vx*=.6;ball.vz*=.6;if(ball.vy<.25)ball.vy=0;}const drag=Math.exp(-h*5);if(ball.y<=.096){ball.vx*=drag;ball.vz*=drag;}}}return state.remaining<=0;}

